import{_ as o,o as e,c as l,ae as r}from"./chunks/framework.Iv6F95cJ.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/network-talk/趣谈网络协议.md","filePath":"books/network-talk/趣谈网络协议.md"}'),_={name:"books/network-talk/趣谈网络协议.md"};function s(a,t,i,n,p,c){return e(),l("div",null,[...t[0]||(t[0]=[r("<p>网络协议是每个程序员入门的必修课，但是彻底掌握并应用网络协议知识却并非易事，比如常见的TCP/IP、HTTP。网络协议的内容很基础，但基础知识不等于简单知识，更不等于不重要的知识。在网络协议的学习过程中，如果你也有过这样的感受：</p><ul><li>协议知识琐碎又枯燥，一看书就头大；</li><li>协议内容很基础，但面试一问就“崩盘”；</li><li>工作遇到才去查书，现学却没法现卖；</li><li>协议知识太底层，不知道如何在热门领域应用。</li></ul><p>那么，“趣谈网络协议”专栏就是为你量身定制的。</p><p>在本专栏中，刘超老师将结合自己从业15年的“泣血”经验，对网络协议的底层概念及其在热门领域的应用进行剖析。</p><p>他选取了从底层到上层，最基础、最常用、最重要的网络协议进行一一解析，并将深入分析网络协议在云计算、容器和微服务等领域的应用和实践。帮助入门级程序员深入、直观地理解网络协议基础概念和原理，构建一个完整、精准的协议知识框架；帮助有一定工作经验的程序员填补知识漏洞、打通知识体系。</p><p>专栏分为3大模块。</p><ul><li><strong>底层网络协议知识详解：</strong> 将用最通俗的语言，自下而上讲解最重要、最常用以及最陌生的网络协议概念，帮你构建最精准的网络协议知识框架。</li><li><strong>网络协议在热门领域的应用：</strong> 将讲述网络协议在当下热门领域的应用，比如云计算、容器和微服务，并手把手带你使用新技术，进一步加深对网络协议概念的理解。</li><li><strong>网络协议知识串联：</strong> 将用“双十一”的故事串起网络协议的核心概念和基础知识；借助虚拟化和容器技术，搭建一个实验环境，持续更新你的知识库。</li></ul>",7)])])}const m=o(_,[["render",s]]);export{k as __pageData,m as default};
